import { useState, useContext } from 'react';
import { useNavigate } from 'react-router-dom';
import AuthContext from '../context/AuthContext';
import axios from 'axios';

import 'bootstrap/dist/css/bootstrap.min.css';
import '@fortawesome/fontawesome-free/css/all.min.css';

export default function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [role, setRole] = useState('SELECT ROLE'); // ✅ NEW STATE

  const { login } = useContext(AuthContext);
  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      const res = await axios.post('http://localhost:5000/api/auth/login', {
        email,
        password,
        role, // ✅ SEND ROLE TO BACKEND
      });

      login(res.data);

      // ✅ Redirect based on role
      if (res.data.user.role === 'admin') {
        navigate('/admin');
      } else {
        navigate('/dashboard');
      }
    } catch (err) {
      alert('Login failed: ' + (err.response?.data?.error || 'Invalid credentials'));
    }
  };

  return (
    <div className="login-container" style={{ height: '100vh', background: '#60a3bc' }}>
      <div className="d-flex justify-content-center align-items-center h-100">
        <div className="user_card" style={{
          height: '430px', // 🔹 Increased height slightly
          width: '350px',
          background: '#f39c12',
          position: 'relative',
          display: 'flex',
          flexDirection: 'column',
          padding: '10px',
          boxShadow: '0 4px 8px rgba(0,0,0,0.2)',
          borderRadius: '5px'
        }}>

          {/* LOGO */}
          <div className="d-flex justify-content-center">
            <div className="brand_logo_container" style={{
              position: 'absolute',
              height: '170px',
              width: '170px',
              top: '-75px',
              borderRadius: '50%',
              background: '#60a3bc',
              padding: '10px'
            }}>
              <img
                src="/logo.png"
                alt="Logo"
                style={{
                  height: '150px',
                  width: '150px',
                  borderRadius: '50%',
                  border: '2px solid white'
                }}
              />
            </div>
          </div>

          {/* FORM */}
          <div className="d-flex justify-content-center form_container" style={{ marginTop: '100px' }}>
            <form onSubmit={handleSubmit} style={{ width: '100%' }}>

              {/* EMAIL */}
              <div className="input-group mb-3">
                <span className="input-group-text" style={{ background: '#c0392b', color: '#fff' }}>
                  <i className="fas fa-user"></i>
                </span>
                <input
                  type="email"
                  className="form-control"
                  value={email}
                  onChange={(e) => setEmail(e.target.value)}
                  placeholder="Email"
                  required
                />
              </div>

              {/* PASSWORD */}
              <div className="input-group mb-3">
                <span className="input-group-text" style={{ background: '#c0392b', color: '#fff' }}>
                  <i className="fas fa-key"></i>
                </span>
                <input
                  type="password"
                  className="form-control"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                  placeholder="Password"
                  required
                />
              </div>

              {/* ✅ ROLE DROPDOWN */}
              <div className="input-group mb-3">
                <span className="input-group-text" style={{ background: '#c0392b', color: '#fff' }}>
                  <i className="fas fa-user-tag"></i>
                </span>
                <select
                  className="form-control"
                  value={role}
                  onChange={(e) => setRole(e.target.value)}
                  required
                >
                  <option value="student">Student</option>
                  <option value="admin">Admin</option>
                </select>
              </div>

              {/* LOGIN BUTTON */}
              <div className="d-flex justify-content-center mt-3">
                <button
                  type="submit"
                  className="btn"
                  style={{ width: '100%', background: '#c0392b', color: '#fff' }}
                >
                  Login
                </button>
              </div>

            </form>
          </div>

          {/* SIGN UP */}
          <div className="mt-4 text-center">
            <span style={{ color: '#fff' }}>
              Don't have an account?{' '}
              <a href="/register" style={{ color: '#fff', textDecoration: 'underline' }}>
                Sign Up
              </a>
            </span>
          </div>

        </div>
      </div>
    </div>
  );
}
